body.usercss:

.container {
    padding: 0;
    box-sizing: border-box;
}
#QaSlkFrm9kP4wNtXc {
    min-height: 280px;
    padding-left: 10px;
    box-sizing: border-box;
}
#QaSlkBdR7mK2pLwNq > .sepoaux_component_outer_wrapper > .sepoaux_component_inner_wrapper > .sepoaux_button_outer {
    width: 100% !important;
    display: flex !important;
    justify-content: flex-end !important;
}
#QaSlkBdR7mK2pLwNq .sepoaux_button_inner.sepoaux_wrapper_style_halign_right {
    margin-left: auto !important;
    margin-right: 12px !important;
    margin-top: 8px !important;
}
#QaSlkBtn8nH3qRxYm {
    float: right !important;
}

userscript.function:

$selectedSealList = [];
$sObject._selectedSealList = $selectedSealList;

var formOptions = [{
    type: "settings",
    position: "label-left",
    labelWidth: 90,
    inputWidth: 340,
    labelAlign: "left"
}, {
    type: "input",
    name: "REQ_SEAL_USE_TYPE",
    label: "날인용도",
    value: "법무검토 완료 계약서",
    readonly: true
}, {
    type: "select",
    name: "RE_FLAG",
    label: "구분",
    required: true,
    options: [{
        text: "전자",
        value: "E",
        selected: true
    }, {
        text: "실물",
        value: "R"
    }]
}, {
    type: "block",
    width: "auto",
    blockOffset: 0,
    list: [{
        type: "input",
        name: "SEAL_NAME",
        label: "인장",
        value: "",
        readonly: true,
        required: true,
        inputWidth: 259
    }, {
        type: "newcolumn"
    }, {
        type: "button",
        name: "SEAL_SELECT",
        value: "선택",
        inputWidth: 60
    }]
}, {
    type: "input",
    name: "SUBJECT",
    label: "신청명",
    value: "",
    required: true,
    maxLength: 200
}, {
    type: "input",
    name: "EXPLANATION",
    label: "설명",
    value: "",
    rows: 4,
    required: true,
    maxLength: 2000
}, {
    type: "input",
    name: "SUBMISSION_PLACE",
    label: "제출처",
    value: "",
    required: true,
    maxLength: 200
}];

var $btnOuter = $($sObject._vp).find('.sepoaux_button_outer').first();
$btnOuter.css({ width: '100%', display: 'flex', justifyContent: 'flex-end' });
$btnOuter.find('.sepoaux_button_inner').css({ marginLeft: 'auto', marginRight: '12px', marginTop: '8px' });

formObj = $sObject.formObj = new SepoaMultiDhtmlXFormObject(formBox, 'formObj', [formOptions], true);
formObj.attachEvent('onButtonClick', onFormButtonClick);
formObj.attachEvent('onChange', onFormChange);
$sObject._selectedReFlag = 'E';

var defaultSubject = Sepoa.request.QNA_SUBJECT || '';
if (defaultSubject && defaultSubject !== 'undefined') {
    formObj.setValue('SUBJECT', defaultSubject);
}


var reFlag = '';
try {
    reFlag = formObj.getValue('RE_FLAG') || formObj.getItemValue('RE_FLAG') || '';
} catch (e) {
    reFlag = '';
}
if (reFlag !== 'E' && reFlag !== 'R') {
    reFlag = $sObject._selectedReFlag || 'E';
}
return reFlag;


$sObject._selectedSealList = [];
try {
    if (Object.prototype.toString.call($selectedSealList) === '[object Array]') {
        $selectedSealList.splice(0, $selectedSealList.length);
    } else {
        $selectedSealList = [];
    }
} catch (e) {
    $selectedSealList = [];
}
if (formObj) {
    formObj.setValue('SEAL_NAME', '');
}


if (name != 'RE_FLAG') {
    return;
}
var nextFlag = (value === 'R') ? 'R' : 'E';
var prevFlag = $sObject._selectedReFlag || 'E';
if (nextFlag === prevFlag) {
    return;
}
var selectedSeals = getSelectedSealList();
if (selectedSeals && selectedSeals.length > 0) {
    Confirm('구분을 변경하면 선택한 인장이 초기화됩니다. 계속하시겠습니까?', function(result) {
        if (!result) {
            // 이전 값으로 복원
            try {
                formObj.setValue('RE_FLAG', prevFlag);
            } catch (e) {
                try { formObj.setItemValue('RE_FLAG', prevFlag); } catch (e2) {}
            }
            return;
        }
        $sObject._selectedReFlag = nextFlag;
        clearSelectedSeal();
    });
} else {
    $sObject._selectedReFlag = nextFlag;
}


var reFlag = getSelectedReFlag();
// ST: 실제 법인인감(C)은 제외. 사용인감(U)·서명인(E)만 (위장 법인인감=U)
var params = {
    SEAL_TYPE: 'U,E',
    SEAL_USE_TYPE: '101',
    APPLY_TYPE: 'U,C',
    FLAGARR: reFlag,
    SELECT_OPTION: 'MULTI'
};
var topWin = SUX.getModuleTop() || window;
var width = Math.min(800, Math.floor((topWin.innerWidth || 1024) * 0.9));
var height = Math.min(540, Math.floor((topWin.innerHeight || 768) * 0.85));
PopupOpenPost(
    '/Seal/Document/Common/Popup/SealDocumentWriteSealPopupLayout.sux',
    params,
    sealSelectCallback,
    width,
    height,
    Sepoa.cache.text.get('SLM_221.SELECT_SEAL') || '인장선택'
);


if (!data) {
    return;
}

// _getSelectedData 결과: { rowId: rowData } 객체 (UseWrite와 동일)
var sealData = [];
var nameArr = [];
for (var i in data) {
    if (!data.hasOwnProperty(i) || !data[i]) {
        continue;
    }
    var sealObj = Object.assign({}, data[i]);
    if (!sealObj.ITEM_NAME) {
        sealObj.ITEM_NAME = sealObj.SUBJECT || '';
    }
    sealData.push(sealObj);
    nameArr.push(sealObj.SUBJECT || sealObj.ITEM_NAME || sealObj.MANAGE_NUMBER);
}

if (sealData.length < 1) {
    return;
}

// ScreenBuilder <var> 재할당 유실 방지: $sObject에 보관이 기준
$sObject._selectedSealList = sealData;
try {
    if (Object.prototype.toString.call($selectedSealList) === '[object Array]') {
        $selectedSealList.splice(0, $selectedSealList.length);
        for (var s = 0; s < sealData.length; s++) {
            $selectedSealList.push(sealData[s]);
        }
    } else {
        $selectedSealList = sealData;
    }
} catch (e) {
    $selectedSealList = sealData;
}

formObj.setValue('SEAL_NAME', nameArr.join(', '));


var list = $sObject._selectedSealList;
if (!list || typeof list.length !== 'number' || list.length < 1) {
    list = $selectedSealList;
}
if (!list || typeof list.length !== 'number') {
    return [];
}
return list;


if (name == 'QA_SEAL_CANCEL') {
    selfObj.close();
    return;
}
if (name != 'QA_SEAL_DO_LINK') {
    return;
}

if (!formObj.validate()) {
    Alert('신청명, 설명, 제출처, 인장을 모두 입력해주세요.');
    return;
}

var subject = $.trim(formObj.getValue('SUBJECT') || '');
var explanation = $.trim(formObj.getValue('EXPLANATION') || '');
var submissionPlace = $.trim(formObj.getValue('SUBMISSION_PLACE') || '');
var selectedSeals = getSelectedSealList();

if (!subject) {
    Alert('신청명을 입력해주세요.');
    return;
}
if (!explanation) {
    Alert('설명을 입력해주세요.');
    return;
}
if (!submissionPlace) {
    Alert('제출처를 입력해주세요.');
    return;
}
if (!selectedSeals || selectedSeals.length < 1) {
    Alert('인장을 선택해주세요.');
    return;
}

var qnaNumber = Sepoa.request.QNA_NUMBER;
if (!qnaNumber || qnaNumber === 'undefined') {
    Alert('문서번호가 없습니다.');
    return;
}

Confirm('입력한 내용으로 날인신청(임시저장)을 생성하시겠습니까?', function(result) {
    if (!result) return;

    // 전체 그리드 row JSON은 파라미터 구분자/필터에 깨질 수 있음 → MANAGE_NUMBER만 전송
    var manageNumbers = [];
    var sealPayload = [];
    for (var i = 0; i < selectedSeals.length; i++) {
        var mn = selectedSeals[i].MANAGE_NUMBER || '';
        if (!mn) continue;
        manageNumbers.push(mn);
        sealPayload.push({ MANAGE_NUMBER: mn });
    }
    if (manageNumbers.length < 1) {
        Alert('인장을 선택해주세요.');
        return;
    }

    var reFlag = getSelectedReFlag();
    doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doSealLink', {
        QNA_NUMBER: qnaNumber,
        SUBJECT: subject,
        EXPLANATION: explanation,
        SUBMISSION_PLACE: submissionPlace,
        RE_FLAG: reFlag,
        RE_DETAIL: reFlag,
        MANAGE_NUMBERS: manageNumbers.join(','),
        SELECT_SEAL_JSON: JSON.stringify(sealPayload)
    }, function(so) {
        if (so.status == 1) {
            var smrNumber = (so.result && so.result[0]) ? so.result[0] : '';
            Alert('날인신청현황에 임시저장 되었습니다.' + (smrNumber ? ('<br/>신청번호: ' + smrNumber) : ''));
            try {
                if (typeof callerObj !== 'undefined' && callerObj && typeof callerObj.sealLinkCallback === 'function') {
                    callerObj.sealLinkCallback(smrNumber);
                }
            } catch (e) {}
            try {
                selfObj.close(smrNumber);
            } catch (e2) {
                selfObj.close();
            }
        } else {
            Alert(so.message || '날인연동에 실패하였습니다.');
        }
    });
});
